INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-27', 'es', 'LAIKA 64 3.6.5: la partida ya no se traba', 'Si una consola deja de responder (se colgó o perdió internet) justo cuando la partida pasa a jugar por el servidor, ya no se quedan todos trabados: a los 15 segundos LAIKA avisa qué jugador dejó de responder. Todos necesitan la misma versión. Actualiza desde LAIKA.'),
 ('2026-11-27', 'en', 'LAIKA 64 3.6.5: games no longer get stuck', 'If a console stops responding (it hung or lost its internet) right as the game switches to the server, nobody is stuck anymore: after 15 seconds LAIKA tells you which player stopped responding. Everyone needs the same version. Update from LAIKA.'),
 ('2026-11-27', 'pt', 'LAIKA 64 3.6.5: a partida não trava mais', 'Se um console parar de responder (travou ou perdeu a internet) bem quando a partida passa a jogar pelo servidor, ninguém fica mais travado: após 15 segundos o LAIKA avisa qual jogador parou de responder. Todos precisam da mesma versão. Atualize pelo LAIKA.'),
 ('2026-11-27', 'fr', 'LAIKA 64 3.6.5 : la partie ne bloque plus', 'Si une console ne répond plus (plantée ou sans internet) au moment où la partie passe par le serveur, plus personne ne reste bloqué : au bout de 15 secondes, LAIKA indique quel joueur ne répond plus. Tous ont besoin de la même version. Mets à jour depuis LAIKA.'),
 ('2026-11-27', 'de', 'LAIKA 64 3.6.5: das Spiel hängt nicht mehr', 'Antwortet eine Konsole nicht mehr (abgestürzt oder ohne Internet), gerade wenn das Spiel auf den Server wechselt, hängt niemand mehr fest: Nach 15 Sekunden zeigt LAIKA, welcher Spieler nicht mehr antwortet. Alle brauchen dieselbe Version. Aktualisiere in LAIKA.'),
 ('2026-11-27', 'it', 'LAIKA 64 3.6.5: la partita non si blocca più', 'Se una console smette di rispondere (bloccata o senza internet) proprio quando la partita passa al server, nessuno resta più bloccato: dopo 15 secondi LAIKA dice quale giocatore ha smesso di rispondere. Tutti devono avere la stessa versione. Aggiorna da LAIKA.'),
 ('2026-11-27', 'ru', 'LAIKA 64 3.6.5: игра больше не зависает', 'Если консоль перестала отвечать (зависла или потеряла интернет) как раз при переходе игры на сервер, никто больше не застревает: через 15 секунд LAIKA сообщит, какой игрок перестал отвечать. Всем нужна одна версия. Обновитесь в LAIKA.');
